      const hpHeatingSection=this.shadowRoot.querySelector("#hpSeparateHeatingDhwSection"),hpDhwSection=this.shadowRoot.querySelector("#hpSeparateDhwMeasurementsSection"),hpCoolingSection=this.shadowRoot.querySelector("#hpCoolingMeasurementsSection");
