    if(page==='energy_status'||page==='energy_plan')return 30000;
    if(page==='finance'||page==='energy_finance'||page==='battery_intelligence')return 45000;
    if(page==='hyper_analytics'||page==='energy_intelligence'||page==='device_intelligence'||page==='intelligence_center'||page==='weather_statistics')return 45000;
