  esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  slug(v){return String(v||'device').toLowerCase().replace(/^sensor\./,'').replace(/[^a-z0-9_]+/g,'_').replace(/^_+|_+$/g,'').slice(0,48)||'device';}
  watts(v){if(v===null||v===undefined||!Number.isFinite(Number(v)))return '—';v=Number(v);return Math.abs(v)>=1000?`${(v/1000).toFixed(Math.abs(v)>=10000?1:2)} kW`:`${Math.round(v)} W`;}
