  kwh(v){const n=Number(v);if(!Number.isFinite(n))return '—';const a=Math.abs(n);if(a>=1000000)return `${(n/1000000).toFixed(2)} GWh`;if(a>=1000)return `${(n/1000).toFixed(2)} MWh`;return `${n.toFixed(2)} kWh`; }
  numberValue(v,fallback=0){if(v===null||v===undefined||v==='')return fallback;if(typeof v==='number')return Number.isFinite(v)?v:fallback;let text=String(v).trim().replace(/\s+/g,'');if(!text)return fallback;text=text.replace(/[^0-9,.-]/g,'');if(text.includes(',')&&text.includes('.')){if(text.lastIndexOf(',')>text.lastIndexOf('.'))text=text.replace(/\./g,'').replace(',','.');else text=text.replace(/,/g,'');}else{text=text.replace(',','.');}const n=Number(text);return Number.isFinite(n)?n:fallback;}
  money(v,currency){const n=this.numberValue(v,NaN),c=String(currency||this.s('sensor.aion_ems_zeus_finance_summary')?.attributes?.currency||'CHF').trim().toUpperCase();return Number.isFinite(n)?`${this.esc(c)} ${n.toFixed(2)}`:'—';}
  displayWindow(v){if(v==null||v==='')return 'Calculating';if(typeof v==='string'){const t=v.trim();if(t==='[object Object]')return 'Calculating';if((t.startsWith('{')||t.startsWith('['))){try{return this.displayWindow(JSON.parse(t));}catch(_e){}}return t;}if(typeof v==='number')return String(v);if(typeof v==='object'){if(v.label||v.title||v.display)return String(v.label||v.title||v.display);const start=v.start||v.start_time||v.from||v.time||v.begin,end=v.end||v.end_time||v.to||v.finish;if(start&&end)return `${String(start).slice(0,16)} – ${String(end).slice(0,16)}`;if(start)return String(start);for(const key of ['window','recommended_window','best_time','best_window','value'])if(v[key]!=null)return this.displayWindow(v[key]);return 'Calculating';}return 'Calculating';}
  friendlyTime(v){if(!v)return '—';const d=new Date(v);if(Number.isNaN(d.getTime()))return String(v);return d.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});}
  copilotEvidenceType(source='',id=''){const t=`${source} ${id}`.toLowerCase();if(/forecast|predictive/.test(t))return 'FORECAST';if(/weather history|history|period|statistics|analytics/.test(t))return 'HISTORY';if(/learning|season/.test(t))return 'LEARNED';if(/recommendation|advisor|scheduler|performance_improve|flexible|ev_charge/.test(t))return 'RECOMMENDATION';if(/energy flow|live|canonical finance|accounting|device analytics|diagnostic|registry/.test(t))return 'LIVE / MEASURED';return 'ZEUS EVIDENCE';}
  copilotWindowExplanation(question='Why is this the best window?'){
    const a=this.s('sensor.aion_ems_zeus_conversational_assistant')?.attributes||{};
    const ctx=a.context_summary||{};
    const forecast=this.s('sensor.aion_ems_zeus_forecast')?.attributes||{};
    const raw=ctx.best_window;
    const label=this.displayWindow(raw);
    const purpose=String(ctx.best_window_purpose||ctx.best_window_type||'').trim();
    const reason=String(ctx.best_window_reason||ctx.best_window_explanation||'').trim();
    const evidence=String(ctx.best_window_source||'Copilot context summary').trim();
    const verified=ctx.best_window_verified===true&&Boolean(reason)&&Boolean(purpose);
    const unverified=!verified;
    const answer=(!raw||label==='Calculating')
      ?'Zeus has not supplied a verified recommendation window. No timing recommendation can be made from the available evidence.'
      :unverified
        ?`Zeus has no verified best window. A suggested time (${label}) exists, but its purpose or supporting calculation has not passed the evidence check. It is not verified for solar surplus, EV charging or low tariffs.`
        :`Zeus reports ${label}${purpose?` for ${purpose}`:''}. ${reason||'The supporting calculation is not available, so this timing is not independently verified.'} Check forecast and tariff evidence before acting.`;
    return {id:'best_window_explanation',question,answer,source:evidence,
      evidence_type:'RECOMMENDATION',mode:'Recommendation only',
      confidence:'—',confidence_note:verified?'Forecast-supported timing; forecast accuracy is not established':'No verified timing evidence',
      context_query:question,verified,
      forecast_status:forecast.status||'unavailable'};
  }
  copilotAnswerMode(q={}){const t=`${q.id||''} ${q.source||''} ${q.question||''}`.toLowerCase();return /recommendation|advisor|scheduler|performance_improve|flexible|should i|when should|what should|ev_charge/.test(t)?'Recommendation only':'Explanation only';}
  copilotAnswerEvidence(q={}){const source=q.source||'Zeus';const type=q.evidence_type||this.copilotEvidenceType(source,q.id||'');return {type,source,mode:q.mode||this.copilotAnswerMode(q)};}
  normalizeCopilotDisplayText(v){
    let text=String(v??'');
    for(let i=0;i<3;i++){
      const next=text
        .replace(/&amp;#x20;|&#x20;|&amp;#32;|&#32;|&amp;nbsp;|&nbsp;|&amp;#160;|&#160;/gi,' ')
        .replace(/\u00a0/g,' ');
      if(next===text)break;
      text=next;
    }
    return text
      .replace(/\*\*([^*]+)\*\*/g,'$1')
      .replace(/[ \t]{2,}/g,' ')
      .replace(/\s+([,.;:!?])/g,'$1')
      .trim();
  }
  copilotAnswerMarkup(q){
    if(!q)return '<p>Copilot will select the most relevant live explanation and show its supporting evidence here.</p>';
    const e=this.copilotAnswerEvidence(q),confidence=q.confidence??'—';
    const answer=this.normalizeCopilotDisplayText(this.humanizeAnswer(q.answer));
    const evidenceType=this.normalizeCopilotDisplayText(e.type);
    const evidenceSource=this.normalizeCopilotDisplayText(e.source);
    const mode=this.normalizeCopilotDisplayText(e.mode);
    const confidenceText=confidence==='—'||confidence===null||confidence===undefined||confidence===''?'Not established':`${String(confidence).replace(/%$/,'')}%`;
    const savedAt=q.time?`<small>Saved answer: ${this.esc(q.time)} · values may have changed since then</small>`:'';
    return `<div class="copilot-answer-block"><span>ANSWER</span><p data-copilot-answer>${this.esc(answer)}</p></div><div class="copilot-answer-evidence"><div><span>EVIDENCE</span><b data-copilot-evidence-type>${this.esc(evidenceType)}</b><small data-copilot-evidence-source>${this.esc(evidenceSource)}</small>${savedAt}</div><div><span>CONFIDENCE</span><b data-copilot-confidence>${this.esc(confidenceText)}</b><small>Evidence strength for this answer</small></div><div><span>MODE</span><b data-copilot-mode>${this.esc(mode)}</b><small>${mode==='Recommendation only'?'Zeus does not control equipment':'Evidence-based explanation'}</small></div></div>`;
  }

