  evChargersPage(){
    const period=this._evChargersPeriod||'today',buttons=['today','week','month','year','total'];
    const registry=this.s('sensor.aion_ems_zeus_registry_summary')?.attributes?.devices||[];
    const analytics=this.s('sensor.aion_ems_zeus_device_analytics')?.attributes?.devices||[];
    const amap=new Map(analytics.map(d=>[String(d.id||''),d]));
    const norm=v=>String(v||'').trim().toLowerCase().replaceAll('-','_').replaceAll(' ','_');
    const chargers=registry.filter(d=>['ev_charger','car_charger','vehicle_charger'].includes(norm(d.type||d.role||d.category))).map(d=>({...d,...(amap.get(String(d.id||''))||{})}));
    const key=({today:'energy_today_kwh',week:'energy_week_kwh',month:'energy_month_kwh',year:'energy_year_kwh',total:'energy_total_kwh'})[period]||'energy_today_kwh';
    const finance=this.s('sensor.aion_ems_zeus_finance_summary')?.attributes||{},cur=String(finance.currency||'CHF').toUpperCase();
    const fv=this.financePeriodValueData(period,finance)||{},importTariff=Math.max(0,Number(fv.finance_import_tariff??finance.import_tariff)||0);
    const flow=this.s('sensor.aion_ems_zeus_energy_flow')?.attributes||{};
    const gridImport=Math.max(0,Number(flow.grid_import_w)||0),gridExport=Math.max(0,Number(flow.grid_export_w)||0);
    const pgridState=this.s('sensor.aion_ems_zeus_ev_surplus_grid_signal');
    const totalPower=chargers.reduce((sum,d)=>{const st=d.power_entity?this.s(String(d.power_entity)):null;return sum+Math.max(0,Number(st?.state)||Number(d.power_w)||0)},0);
    const totalEnergy=chargers.reduce((sum,d)=>sum+Math.max(0,Number(d[key])||0),0);
    const equivalentCost=totalEnergy*importTariff;
    const goe=chargers.filter(d=>String(d.device_profile||'')==='go_e_charger_mqtt');
    const signedGrid=Number.isFinite(Number(pgridState?.state))?Math.round(Number(pgridState.state)):Math.round(gridImport>0?gridImport:gridExport>0?-gridExport:0);
    const cards=chargers.map((d,i)=>{const powerState=d.power_entity?this.s(String(d.power_entity)):null,power=Math.max(0,Number(powerState?.state)||Number(d.power_w)||0),energy=Math.max(0,Number(d[key])||0),cost=energy*importTariff,name=d.name||d.friendly_name||`EV Charger ${i+1}`,profile=String(d.device_profile||'').replaceAll('_',' '),available=powerState? !['unavailable','unknown'].includes(String(powerState.state).toLowerCase()):true;return `<article class="panel ev-charger-card"><div class="section-title"><div><span>CHARGER ${i+1}</span><h2>${this.esc(name)}</h2></div><ha-icon icon="mdi:ev-station"></ha-icon></div><div class="energy-statistics-grid"><div class="energy-statistics-card"><ha-icon icon="mdi:flash"></ha-icon><div><span>Live power</span><b>${this.watts(power)}</b><small>${available?(power>0?'Charging':'Idle'):'Unavailable'}</small></div></div><div class="energy-statistics-card"><ha-icon icon="mdi:counter"></ha-icon><div><span>${this.periodLabel(period)} energy</span><b>${this.kwh(energy)}</b><small>Measured registered charger energy</small></div></div><div class="energy-statistics-card"><ha-icon icon="mdi:cash-multiple"></ha-icon><div><span>Grid-equivalent value</span><b>${this.money(cost,cur)}</b><small>${importTariff>0?`${this.money(importTariff,cur)}/kWh import tariff`:'Configure import tariff for finance'}</small></div></div><div class="energy-statistics-card"><ha-icon icon="mdi:identifier"></ha-icon><div><span>Evidence</span><b>${d.energy_entity?'Energy mapped':d.power_entity?'Power mapped':'Unavailable'}</b><small>${this.esc(profile||'Registered EV charger')}</small></div></div></div>${String(d.device_profile||'')==='go_e_charger_mqtt'?`<div class="ev-mqtt-strip" style="margin-top:14px;padding:0 0 8px 2px;line-height:1.35"><b>pGrid ${signedGrid} W</b></div>`:''}</article>`}).join('');
    return `<section class="page ev-chargers-page"><div class="analytics-topbar"><div><span class="eyebrow">EV CHARGERS</span><h1>Charging & Finance</h1><p>Registered EV charging, measured energy and tariff-based financial context. Zeus reports evidence only and does not infer missing charger data.</p></div><div class="period-switch">${buttons.map(x=>`<button type="button" data-ev-chargers-period="${x}" class="period-button ${period===x?'selected':''}">${this.periodLabel(x)}</button>`).join('')}</div></div><div class="kpi-grid"><article class="panel energy-kpi-card"><span>REGISTERED</span><strong>${chargers.length}</strong><small>EV chargers</small></article><article class="panel energy-kpi-card"><span>LIVE POWER</span><strong>${this.watts(totalPower)}</strong><small>Combined registered chargers</small></article><article class="panel energy-kpi-card"><span>${this.periodLabel(period).toUpperCase()} ENERGY</span><strong>${this.kwh(totalEnergy)}</strong><small>Measured charger demand</small></article><article class="panel energy-kpi-card"><span>GRID-EQUIVALENT VALUE</span><strong>${this.money(equivalentCost,cur)}</strong><small>${importTariff>0?'At configured import tariff':'Tariff unavailable'}</small></article></div><article class="panel spaced"><div class="section-title"><div><span>LIVE GRID CONTEXT</span><h2>Charging against the house energy balance</h2></div><ha-icon icon="mdi:transmission-tower"></ha-icon></div><div class="tariff-summary-grid"><div><span>Grid import</span><b>${this.watts(gridImport)}</b></div><div><span>Grid export</span><b>${this.watts(gridExport)}</b></div><div><span>go-e signal</span><b>${goe.length?`${signedGrid} W`:'Unavailable'}</b><small>${goe.length?'Signed pGrid · export negative, import positive':'No registered go-e MQTT charger'}</small></div><div><span>Battery signal</span><b>${goe.length?'0 W':'Unavailable'}</b><small>${goe.length?'pAkku intentionally unused':'No go-e MQTT evidence'}</small></div></div></article>${cards||`<article class="panel spaced"><div class="empty">No registered EV chargers are available. Add an EV charger in Device Manager to populate this page.</div></article>`}<article class="panel spaced"><div class="section-title"><div><span>FINANCE EVIDENCE</span><h2>What the value means</h2></div><ha-icon icon="mdi:shield-check-outline"></ha-icon></div><p class="muted-note">Grid-equivalent value is measured charger energy multiplied by the configured import tariff. It is not presented as actual grid cost when source attribution cannot prove how much charging energy came from solar, battery or grid.</p></article></section>`;
  }

  patchEvChargersPGridDom(){
    if(this._page!=='ev_chargers')return;
    const state=this.s('sensor.aion_ems_zeus_ev_surplus_grid_signal');
    const value=Number(state?.state);
    if(!Number.isFinite(value))return;
    const signed=Math.round(value);
    this.querySelectorAll('.ev-mqtt-strip b').forEach(node=>{node.textContent=`pGrid ${signed} W`;});
  }

