  _sanitizeDiagnosticExport(value){
    if(value==null) return value;
    if(Array.isArray(value)) return value.map(v=>this._sanitizeDiagnosticExport(v));
    if(typeof value==='object'){
      const out={};
      for(const [k,v] of Object.entries(value)){
        const key=String(k||'').toLowerCase();
        if(/password|passwd|token|secret|api[_-]?key|access[_-]?key|mqtt.*(user|pass)|username/.test(key)) continue;
        if(key==='server'||key==='host'||key==='hostname'||key==='ip'||key==='ip_address'||key==='address') { out[k]='[redacted]'; continue; }
        // Package/frontend versions are support-critical metadata, not network addresses.
        // Preserve them before the generic IPv4-looking string sanitizer runs.
        if((key==='zeus_version'||key==='frontend_version'||key==='version') && typeof v==='string') { out[k]=v; continue; }
        out[k]=this._sanitizeDiagnosticExport(v);
      }
      return out;
    }
    if(typeof value==='string'){
      let t=value;
      // IPv4 and bracketed/unbracketed IPv6-like literals in human-readable diagnostic text.
      t=t.replace(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g,'[redacted-address]');
      t=t.replace(/\b(?:[A-Fa-f0-9]{1,4}:){2,}[A-Fa-f0-9]{0,4}\b/g,'[redacted-address]');
      // Common URI credentials: scheme://user:password@host
      t=t.replace(/([a-z][a-z0-9+.-]*:\/\/)[^\s/@:]+:[^\s/@]+@/gi,'$1[redacted]@');
      return t;
    }
    return value;
  }
  diagnosticReportText(){return JSON.stringify(this.diagnosticReportData(),null,2);}
  downloadDiagnosticReport(){const text=this._diagnosticReport||this.diagnosticReportText(),blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`AION_EMS_Zeus_Diagnostic_Report_${this.localDateKey()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  supportSummaryText(){
    const r=this.diagnosticReportData(),sys=r.system||{},flow=r.energy_flow||{},sc=r.smart_control||{},qa=r.self_test||{};
    const devices=Array.isArray(r.registered_devices)?r.registered_devices:[];
    const byType={}; for(const d of devices){const t=String(d.type||'other').replaceAll('_',' ');byType[t]=(byType[t]||0)+1;}
    const typeText=Object.entries(byType).sort((a,b)=>a[0].localeCompare(b[0])).map(([k,v])=>`${k}: ${v}`).join(', ');
    const latency=Number(flow.update_latency_ms);
    const fmtMs=n=>Number.isFinite(n)?(n>=10000?`${(n/1000).toFixed(1)} s`:`${n.toFixed(0)} ms`):'Unavailable';
    const sims=Array.isArray(sc.simulations)?sc.simulations:[],goe=Array.isArray(sc.goe_mqtt)?sc.goe_mqtt:[];
    const controlLines=[];
    for(const d of (Array.isArray(sc.devices)?sc.devices:[])){
      const sim=sims.find(x=>x.device_id===d.device_id),g=goe.find(x=>x.device_id===d.device_id);
      if(sim){const state=sim.allowed?'READY':'BLOCKED';controlLines.push(`- ${d.name||d.device_id}: ${state} · request ${sim.requested_power_w??0} W${sim.reason?` · ${sim.reason}`:''}`);}
      else if(g){controlLines.push(`- ${d.name||d.device_id}: ${g.active?'PUBLISHING':'INACTIVE'} · MQTT ${g.last_error?'error':'healthy'}`);}
      else controlLines.push(`- ${d.name||d.device_id}: ${d.permission_granted?'permission granted':'observe only'}`);
    }
    const warnings=[];
    if(String(qa.status||'').toLowerCase()&&!/healthy|passed|ok/.test(String(qa.status||'').toLowerCase()))warnings.push(`Self-test status: ${qa.status}`);
    if(Number(qa.warnings)>0)warnings.push(`${qa.warnings} self-test warning(s)`); if(Number(qa.errors)>0)warnings.push(`${qa.errors} self-test error(s)`);

    // v14.8.10.12: include the canonical Energy Sources mappings in the
    // privacy-safe forum summary. This is deliberately limited to energy
    // source fields (not the complete registry/device mapping set) so support
    // can verify configuration without exposing connection details.
    const mappingAttrs=this.s('sensor.aion_ems_zeus_energy_mapping')?.attributes||{};
    const sourceMappings=mappingAttrs.mappings||this.s('sensor.aion_ems_zeus_registry_summary')?.attributes?.entity_mappings||{};
    const sourceFields=[
      ['house_power','Home consumption power'],
      ['solar_power','Solar production power'],
      ['grid_power','Bidirectional grid power'],
      ['grid_import_power','Grid import power'],
      ['grid_export_power','Grid export power'],
      ['battery_soc','Battery state of charge'],
      ['battery_power','Bidirectional battery power'],
      ['battery_charge_power','Battery charge power'],
      ['battery_discharge_power','Battery discharge power'],
      ['house_energy_today','Home consumption today'],
      ['solar_energy_today','Solar production today'],
      ['grid_import_energy_today','Grid import today'],
      ['grid_export_energy_today','Grid export today'],
      ['battery_charge_energy_today','Battery charged today'],
      ['battery_discharge_energy_today','Battery discharged today'],
      ['house_energy_total','Home consumption lifetime'],
      ['solar_energy_total','Solar production lifetime'],
      ['grid_import_energy_total','Grid import lifetime'],
      ['grid_export_energy_total','Grid export lifetime'],
      ['battery_charge_energy_total','Battery charged lifetime'],
      ['battery_discharge_energy_total','Battery discharged lifetime']
    ];
    const sourceLines=sourceFields.map(([field,label])=>{
      const raw=sourceMappings?.[field];
      const eid=String((raw&&typeof raw==='object'?raw.entity_id:raw)||'').trim();
      if(!eid)return `- ${label}: Not mapped`;
      const st=this.s(eid);
      if(!st)return `- ${label}: ${eid} · Unavailable`;
      const state=String(st.state??'—');
      const unit=String(st.attributes?.unit_of_measurement||'').trim();
      const availability=['unknown','unavailable'].includes(state.toLowerCase())?` · ${state}`:` · ${state}${unit?` ${unit}`:''}`;
      return `- ${label}: ${eid}${availability}`;
    });
    const batteryOptions=mappingAttrs.mapping_options||{};
    const batteryMode=String(batteryOptions.battery_mode||((sourceMappings.battery_charge_power||sourceMappings.battery_discharge_power)?'separate':sourceMappings.battery_power?'bidirectional':'not configured'));
    const batterySign=String(batteryOptions.battery_power_sign||'not set');
    sourceLines.push(`- Battery mapping mode: ${batteryMode}${batteryMode==='bidirectional'?` · sign convention ${batterySign}`:''}`);

    const text=[
      'AION EMS Zeus Support Summary',
      `Generated: ${r.generated_at||new Date().toISOString()}`,
      '',
      `Zeus: v${sys.zeus_version||'Unknown'} · Frontend: v${sys.frontend_version||'Unknown'}`,
      `System health: ${qa.status||flow.status||'Unknown'}${qa.score!=null?` · Self-test ${qa.score}% ${qa.grade||''}`:''}`,
      `Registered devices: ${sys.registered_devices??devices.length}${typeText?` (${typeText})`:''}`,
      '',
      'Energy Flow',
      `- Status: ${flow.status||'Unknown'}`,
      `- House: ${flow.house_power_w??'—'} W · Solar: ${flow.solar_power_w??'—'} W · Grid import: ${flow.grid_import_power_w??'—'} W · Grid export: ${flow.grid_export_power_w??'—'} W`,
      `- Update latency: ${fmtMs(latency)}`,
      '',
      'Energy Sources',
      ...sourceLines,
      '',
      'Smart Control',
      ...(controlLines.length?controlLines:['- No supervised controllable devices reported.']),
      '',
      'Self-Test',
      `- ${qa.status||'Not run'}${qa.score!=null?` · ${qa.score}% · ${qa.grade||'—'}`:''} · Passed ${qa.passed??'—'} · Warnings ${qa.warnings??'—'} · Errors ${qa.errors??'—'}`,
      '',
      'Important warnings',
      ...(warnings.length?warnings.map(x=>`- ${x}`):['- None reported.']),
      '',
      'Privacy: shortened support summary; includes only Energy Sources mappings and live values. No credentials, tokens, server addresses, or secret connection data.'
    ].join('\n');
    return this._sanitizeDiagnosticExport(text);
  }
