  energyStatisticsPanel(metric,label){
    const analytics=this.historicalData(),periods=analytics.periods||{};
    const keys={
      battery_charge:'battery_charge_energy_kwh',
      battery_discharge:'battery_discharge_energy_kwh',
      grid_import:'grid_import_energy_kwh',
      grid_export:'grid_export_energy_kwh'
    };
    const key=keys[metric]||`${metric}_energy_kwh`;
    const today=this.measuredToday(periods.today||analytics.today||{});
    const sources=[
      ['Today',today],
      ['This week',periods.week||analytics.week||{}],
      ['This month',periods.month||analytics.month||{}],
      ['This year',periods.year||analytics.year||{}]
    ];
    const valueFrom=source=>{
      const candidates=[source?.[key],source?.[metric],source?.[`${metric}_kwh`]];
      for(const candidate of candidates){const value=Number(candidate);if(Number.isFinite(value))return Math.max(0,value);}
      return null;
    };
    const isExport=metric==='grid_export',isDischarge=metric==='battery_discharge';
    const iconFor=(period,index)=>index===0?(isExport||isDischarge?'mdi:tray-arrow-up':'mdi:tray-arrow-down'):(period==='This month'?'mdi:calendar-month-outline':'mdi:calendar-outline');
    return `<article class="panel spaced energy-statistics-panel ${isExport||isDischarge?'energy-statistics-positive':''}"><div class="section-title"><div><span>STATISTICS</span><h2>${this.esc(label)} history</h2></div><small>Measured energy</small></div><div class="energy-statistics-grid">${sources.map(([period,source],index)=>`<div class="energy-statistics-card"><ha-icon icon="${iconFor(period,index)}"></ha-icon><div><span>${period}</span><b>${this.kwh(valueFrom(source))}</b><small>${this.esc(label)}</small></div></div>`).join('')}</div></article>`;
  }

  gridStatisticsPage(){return this.smartMeterPage();}

