  async ensureHeatPumpDayHistory(){
    if(this._hpDayHistoryLoading||this._hpDayHistoryLoaded||!this._hass?.callWS)return;
    this._hpDayHistoryLoading=true;
    try{this._hpDayHistory=await this._hass.callWS({type:'aion_ems_zeus/heat_pump_day_history'});this._hpDayHistoryError='';}
    catch(e){this._hpDayHistory={series:[]};this._hpDayHistoryError=e?.message||String(e);}
    finally{this._hpDayHistoryLoading=false;this._hpDayHistoryLoaded=true;if(this.isConnected&&['heat_pump_day_status','dhw_day_status'].includes(this._page)){this._lastSignatureByPage?.delete(this._page);this.render();}}
  }

  async ensureBatteryDayHistory(){
    if(this._batteryDayLoading||this._batteryDayLoaded)return;this._batteryDayLoading=true;
    try{this._batteryDayHistory=await this._hass.callWS({type:'aion_ems_zeus/battery_day_history'});this._batteryDayError='';}
    catch(e){this._batteryDayHistory={series:[]};this._batteryDayError=String(e?.message||e||'Recorder unavailable');}
    finally{this._batteryDayLoading=false;this._batteryDayLoaded=true;if(this.isConnected&&this._page==='battery_day_status'){this._lastSignatureByPage?.delete('battery_day_status');this.render();}}
  }
