    const ageLabel=m=>m==null?'No update':m<1?'Updated now':m<60?`${Math.round(m)} min ago`:m<1440?`${Math.round(m/60)} h ago`:`${Math.round(m/1440)} d ago`,trendLabel=r=>r.trend==='improving'?`Improving +${r.delta.toFixed(0)}`:r.trend==='declining'?`Declining ${r.delta.toFixed(0)}`:r.trend==='new'?'New baseline':'Stable',trendIcon=r=>r.trend==='improving'||r.recovered?'mdi:trending-up':r.trend==='declining'?'mdi:trending-down':r.trend==='new'?'mdi:new-box':'mdi:trending-neutral';
