    const rows=deaDevices.map(item=>{const base=meta.get(String(item.id))||{},a=item?.periods?.[period]||null;if(!a)return null;const merged={...base,...item,name:base.name||item.name||item.id,type:base.type||item.type||'load'};if(!isLoad(merged))return null;const e=n(a.energy_kwh??a.total_kwh),solar=n(a.solar_kwh),battery=n(a.battery_kwh),grid=n(a.grid_kwh),saved=(solar+battery)*importTariff;return {...merged,energy:e,solar,battery,grid,saved,local:solar+battery,quality:String(a.quality||'Estimated period allocation')};}).filter(Boolean).sort((a,b)=>b.saved-a.saved);
